function login(message=''){frame('<h2>Masuk</h2><p class="note">Gunakan akun yang didaftarkan oleh pengelola.</p><form id="form"><label for="email">Username</label><div class="input-wrap"><span class="field-icon" aria-hidden="true">✉</span><input type="text" id="email" autocomplete="username" placeholder="Masukkan username Anda" required></div><label for="password">Kata sandi</label><div class="input-wrap password-wrap"><span class="field-icon" aria-hidden="true">♙</span><input type="password" id="password" autocomplete="current-password" placeholder="Masukkan kata sandi Anda" required><button type="button" id="toggle" class="toggle-password" aria-label="Tampilkan kata sandi">◉ Lihat</button></div><button type="submit" id="submit" class="submit">Masuk ke GASPOS <span aria-hidden="true">→</span></button><p id="msg" role="alert"></p></form>');document.getElementById('msg').textContent=message;document.getElementById('toggle').onclick=()=>{const p=document.getElementById('password'),t=document.getElementById('toggle');const show=p.type==='password';p.type=show?'text':'password';t.textContent=show?'◉ Sembunyikan':'◉ Lihat';t.setAttribute('aria-label',show?'Sembunyikan kata sandi':'Tampilkan kata sandi')};document.getElementById('form').onsubmit=async e=>{e.preventDefault();if(!api){document.getElementById('msg').textContent='Konfigurasi Supabase belum dipasang.';return}const btn=document.getElementById('submit');btn.disabled=true;try{const{data,error}=await api.auth.signInWithPassword({email:(document.getElementById('email').value.trim().toLowerCase()==='owner'?'owner@gaspos.com':(document.getElementById('email').value.trim().includes('@')?document.getElementById('email').value.trim():document.getElementById('email').value.trim().toLowerCase()+'@users.gaspos.local')),password:document.getElementById('password').value});if(error)throw error;await enter(data.user)}catch(err){const msg=document.getElementById('msg');const code=err?.code||'';const status=err?.status;const detail=(err?.message||'').toLowerCase();if(code==='email_not_confirmed'||detail.includes('email not confirmed'))msg.textContent='Akun Owner belum diaktifkan di Supabase Auth. Hubungi administrator.';else if(code==='invalid_credentials'||detail.includes('invalid login credentials'))msg.textContent='Akun atau kata sandi tidak cocok. Hubungi pengelola GASPOS untuk pengaturan akun.';else if(detail.includes('fetch')||detail.includes('network'))msg.textContent='Tidak dapat terhubung ke Supabase. Periksa internet dan coba kembali.';else msg.textContent='Login gagal ('+(code||status||'tidak diketahui')+'). '+(err?.message||'Silakan coba lagi.');btn.disabled=false}}}
