 const render=()=>{const q=search.value.trim().toLowerCase();const results=suppliers.filter(p=>[p.name,p.phone,p.address].some(v=>String(v||'').toLowerCase().includes(q)));total.textContent=results.length+' supplier';rows.innerHTML=results.length?results.map(p=>'<tr><td class="supplier-name">'+htmlEscape(p.name)+'</td><td>'+htmlEscape(p.phone||'—')+'</td><td class="supplier-address">'+htmlEscape(p.address||'—')+'</td><td class="supplier-action-cell">'+(role==='OWNER'?'<button type="button" class="supplier-edit" data-supplier-id="'+p.id+'">Edit</button>':'—')+'</td></tr>').join(''):'<tr><td colspan="4" class="supplier-empty">Belum ada supplier yang sesuai.</td></tr>'};
