 if([pr,hist,balances].some(x=>x.error)){rows.innerHTML='<tr><td colspan="3" class="product-empty">Gagal memuat stok.</td></tr>';history.innerHTML='';return}
 const products=pr.data||[],prodMap=new Map(products.map(x=>[x.id,x])),totals=new Map((balances.data||[]).map(x=>[x.product_id,[Number(x.full_balance),Number(x.empty_balance)]]));
 rows.innerHTML=products.length?products.map(x=>{const n=totals.get(x.id)||[0,0];return '<tr><td>'+htmlEscape(x.code+' — '+x.name)+'</td><td>'+n[0]+'</td><td>'+n[1]+'</td></tr>'}).join(''):'<tr><td colspan="3" class="product-empty">Belum ada produk.</td></tr>';
 const signed=n=>(n>0?'+':'')+n;
 history.innerHTML=(hist.data||[]).length?hist.data.slice(0,50).map(x=>'<tr><td>'+htmlEscape(x.document_no)+'</td><td>'+htmlEscape(prodMap.get(x.product_id)?.name||'—')+'</td><td>'+signed(x.delta_full)+'</td><td>'+signed(x.delta_empty)+'</td></tr>').join(''):'<tr><td colspan="4" class="product-empty">Belum ada mutasi.</td></tr>';
 if(role!=='OWNER')return;
